  /* Stock — what is on the shelf, and everything a person does to it (B4).
   *
   * Two of these carry a decision rather than a label.
   *
   * `stock.countBlind` explains why the count sheet does not show the expected
   * figure. A person told the system expects fourteen counts to fourteen, and a
   * count that confirms the records is worth nothing — so the sheet withholds
   * it and this sentence says so, because a blank column with no explanation
   * reads as a bug.
   *
   * `stock.shortBy` is a transfer whose destination confirmed less than was
   * sent. The stock is not lost and not written off: it is still the company's,
   * still in the valuation, and somebody has to decide with a reason attached
   * that it is gone. The wording must not imply the system has dealt with it. */

