  /* Cash and bank (C2), and the reconciliation (C11).
   *
   * `recon.unexplained` is the one that carries a decision. C11's whole value
   * is refusing to sign off a difference nobody accounts for, and the sentence
   * has to make that read as a finding rather than as an error the screen has
   * made. The Reconcile button is absent while it shows, not disabled: a
   * disabled button invites pressing and an explanation invites reading.
   *
   * `recon.csvProblem.*` are the parser's answers. It returns a key and a row
   * number rather than a sentence, because the parser has no translator and one
   * that returned English would put a hardcoded string on an Arabic screen. */

