  'nx.pbk.uploadNote': "যে সার্ভারকে নিজে না-নেওয়া ব্যাকআপ থেকে ফিরতে হবে তার জন্য — নতুন মেশিন, বা যার স্টোর হারিয়ে গেছে। আপলোড করা কিছুকেই বিশ্বাস করা হয় না: নিজের ম্যানিফেস্টের সঙ্গে মিলিয়ে দেখা হয়, আর ফিরিয়ে মিলিয়ে দেখার পরেই কেবল সেটি ব্যাকআপ হিসেবে গণ্য হয়।",
