  'nx.pitr.help.beforeTime': "আপনার দেওয়া মুহূর্তের ঠিক আগে থামে, তাই ঠিক সেই মুহূর্তে সম্পন্ন হওয়া লেনদেন বাদ পড়ে। ভুলটি কখন ঘটেছে জানা থাকলে এটিই বেছে নিন।",
