  'nx.pitr.help.lsn': "লগের একটি নির্দিষ্ট অবস্থানে থামে। অনুসন্ধান থেকে অবস্থানটি আগেই জানা থাকলে ব্যবহার করুন।",
  'nx.pitr.help.name': "ঝুঁকিপূর্ণ পরিবর্তনের আগে কেউ ইচ্ছে করে রাখা বিন্দুতে থামে। ঘড়ির চেয়ে নিরাপদ, কারণ এটি মুহূর্ত অনুমান না করে নাম ধরে বলে।",

